'use strict';

// MODULES //

var tape = require( 'tape' );
var wrap = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof wrap, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function throws an error if provided an `options` argument which is not an object', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		5,
		NaN,
		true,
		null,
		void 0,
		[],
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws a type error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function throws() {
			wrap( 'hello world', value );
		};
	}
});

tape( 'the function throws an error if provided an `indent` option which is not a nonnegative integer', function test( t ) {
	var values;
	var i;

	values = [
		-1,
		3.14,
		NaN,
		'5',
		true,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws a type error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function throws() {
			var opts = {
				'indent': value
			};
			wrap( 'hello world', opts );
		};
	}
});

tape( 'the function throws an error if provided a `maxWidth` option which is not a positive integer', function test( t ) {
	var values;
	var i;

	values = [
		0,
		-1,
		3.14,
		NaN,
		'5',
		true,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws a type error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function throws() {
			var opts = {
				'maxWidth': value
			};
			wrap( 'hello world', opts );
		};
	}
});

tape( 'the function throws an error if `options.maxWidth` is less than or equal to `options.indent`', function test( t ) {
	t.throws( badValue( 4 ), RangeError, 'throws a range error' );
	t.throws( badValue( 3 ), RangeError, 'throws a range error' );
	t.end();

	function badValue( maxWidth ) {
		return function throws() {
			var opts = {
				'indent': 4,
				'maxWidth': maxWidth
			};
			wrap( 'hello world', opts );
		};
	}
});

tape( 'the function returns an empty string for empty text', function test( t ) {
	var actual = wrap( '' );

	t.strictEqual( actual, '', 'returns expected value' );
	t.end();
});

